import React from 'react';
import { Button, SmileyColor, SmileyProps, Text } from '../../atoms';
import { AlignEnum, ColorNameEnum, SizeEnum, WeightEnum } from '../../types';

export interface ClickableSmileyProps {
  name: string;
  textColor?: ColorNameEnum;
  fontWeight?: WeightEnum;
  fontSize?: SizeEnum;
  isSelected: boolean;
  color?: SmileyColor;
  onClick?: () => void;
  SmileyComponent: React.FC<SmileyProps>;
}

function ClickableSmiley({
  name,
  textColor,
  fontWeight,
  fontSize,
  isSelected,
  color,
  onClick,
  SmileyComponent,
}: ClickableSmileyProps) {
  return (
    <Button key={name} buttonType="link" onClick={onClick}>
      <SmileyComponent selected={isSelected} color={color ?? SmileyColor.Default} />
      <Text
        text={name}
        colorName={textColor ?? ColorNameEnum.theme}
        weight={fontWeight}
        align={AlignEnum.center}
        size={fontSize ?? SizeEnum['14px']}
      />
    </Button>
  );
}

export default ClickableSmiley;
